}
.membership-stat .stat-info p {
  font-size: 0.938rem;
  color: var(--gray-500);
}
@media (max-width: 640px) {
  .membership-stat { flex-direction: column; text-align: center; }
  .membership-stat .big-number { font-size: 2.5rem; }
}

/* ───── ANIMATIONS ───── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
