@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800&display=swap');

:root {
  --primary: #4F46E5;
  --primary-dark: #3730A3;
  --primary-light: #818CF8;
  --primary-50: #EEF2FF;
  --accent: #10B981;
  --accent-dark: #059669;
  --coral: #F43F5E;
  --lime: #E6FF32;
  --dark: #0F172A;
  --gray-900: #1E293B;
  --gray-700: #334155;
  --gray-500: #64748B;
  --gray-300: #CBD5E1;
  --gray-100: #F1F5F9;
  --gray-50: #F8FAFC;
  --white: #FFFFFF;
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 4px 12px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 8px 30px rgba(15, 23, 42, 0.12);
  --shadow-xl: 0 20px 60px rgba(15, 23, 42, 0.15);
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font-sans);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ───── NAVBAR ───── */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  transition: box-shadow 0.3s ease;
}
.navbar.scrolled { box-shadow: var(--shadow-md); }
.navbar-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.navbar-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.navbar-logo .logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.1rem;
  font-weight: 800;
}
.nav-links { display: flex; align-items: center; gap: 0.25rem; list-style: none; }
.nav-links a {
  text-decoration: none;
  color: var(--gray-700);
  font-weight: 500;
  font-size: 0.938rem;
  padding: 0.5rem 0.875rem;
  border-radius: var(--radius);
  transition: all 0.2s ease;
}
.nav-links a:hover { color: var(--primary); background: var(--primary-50); }
.nav-links a.active { color: var(--primary); background: var(--primary-50); }
.nav-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--primary);
  color: var(--white) !important;
  font-weight: 600 !important;
  padding: 0.625rem 1.25rem !important;
  border-radius: var(--radius) !important;
  transition: all 0.2s ease !important;
  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3);
}
.nav-cta:hover { background: var(--primary-dark) !important; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(79, 70, 229, 0.4) !important; }
.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--gray-700);
}
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  padding: 1.5rem;
  flex-direction: column;
  gap: 0.5rem;
  overflow-y: auto;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  text-decoration: none;
  color: var(--gray-700);
  font-weight: 500;
  font-size: 1.1rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius);
  transition: all 0.2s ease;
}
.mobile-nav a:hover { color: var(--primary); background: var(--primary-50); }
.mobile-nav .nav-cta-mobile {
  display: block;
  text-align: center;
  background: var(--primary);
  color: var(--white);
  font-weight: 600;
  padding: 0.875rem 1.25rem;
  border-radius: var(--radius);
  margin-top: 1rem;
}

@media (max-width: 1024px) {
  .nav-links { display: none; }
  .hamburger { display: block; }
}

/* ───── SECTIONS ───── */
.section { padding: 5rem 1.5rem; }
.section-sm { padding: 3rem 1.5rem; }
.container { max-width: 1200px; margin: 0 auto; }
.container-narrow { max-width: 900px; margin: 0 auto; }
.section-label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.813rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  background: var(--primary-50);
  padding: 0.375rem 1rem;
  border-radius: 100px;
  margin-bottom: 1rem;
}
.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  line-height: 1.15;
  color: var(--dark);
  margin-bottom: 1rem;
}
.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-500);
  line-height: 1.7;
  max-width: 640px;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ───── HERO ───── */
.hero {
  padding-top: 8rem;
  padding-bottom: 4rem;
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--white) 50%, #ECFDF5 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(79, 70, 229, 0.06) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; text-align: center; }
.hero-title {
  font-size: clamp(2.5rem, 5.5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  color: var(--dark);
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}
.hero-title .highlight {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-500);
  max-width: 640px;
  margin: 0 auto 2.5rem;
  line-height: 1.7;
}
.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

/* ───── BUTTONS ───── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 1rem;
  padding: 0.875rem 2rem;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
  line-height: 1;
}
.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 2px 12px rgba(79, 70, 229, 0.35);
}
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-2px); box-shadow: 0 6px 24px rgba(79, 70, 229, 0.4); }
.btn-secondary {
  background: var(--white);
  color: var(--gray-700);
  border: 1.5px solid var(--gray-300);
}
.btn-secondary:hover { border-color: var(--primary); color: var(--primary); }
.btn-accent {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 2px 12px rgba(16, 185, 129, 0.35);
}
.btn-accent:hover { background: var(--accent-dark); transform: translateY(-2px); }
.btn-lg { padding: 1rem 2.5rem; font-size: 1.063rem; }
.btn-sm { padding: 0.5rem 1.25rem; font-size: 0.875rem; }
.btn-ghost { background: transparent; color: var(--gray-700); }
.btn-ghost:hover { background: var(--gray-100); }

/* ───── HERO TABS ───── */
.hero-tabs {
  display: inline-flex;
  background: var(--white);
  border-radius: 100px;
  padding: 4px;
  box-shadow: var(--shadow-md);
  margin-bottom: 2rem;
  border: 1px solid var(--gray-100);
}
.hero-tab {
  padding: 0.625rem 1.5rem;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.938rem;
  cursor: pointer;
  transition: all 0.25s ease;
  border: none;
  background: transparent;
  color: var(--gray-500);
  font-family: var(--font-sans);
}
.hero-tab.active { background: var(--primary); color: var(--white); box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3); }
.hero-tab:hover:not(.active) { color: var(--primary); }

.hero-preview {
  max-width: 960px;
  margin: 0 auto;
  position: relative;
}
.hero-preview-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  border: 1px solid rgba(0, 0, 0, 0.06);
  overflow: hidden;
  padding: 1.5rem;
}
.preview-panel { display: none; animation: fadeUp 0.4s ease-out; }
.preview-panel.active { display: block; }

.preview-mockup {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 340px;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.mockup-topbar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--gray-300);
}
.mockup-dot { width: 10px; height: 10px; border-radius: 50%; }
.mockup-dot.r { background: #EF4444; }
.mockup-dot.y { background: #F59E0B; }
.mockup-dot.g { background: #10B981; }
.mockup-urlbar {
  flex: 1;
  margin-left: 0.75rem;
  background: var(--white);
  border-radius: 6px;
  padding: 0.375rem 0.75rem;
  font-size: 0.813rem;
  color: var(--gray-500);
}
.mockup-body { flex: 1; display: flex; flex-direction: column; gap: 1rem; }
.mockup-sidebar {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 1.5rem;
  flex: 1;
}
.mockup-nav-items { display: flex; flex-direction: column; gap: 0.5rem; }
.mockup-nav-item {
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  font-size: 0.813rem;
  color: var(--gray-500);
  background: var(--white);
}
.mockup-nav-item.active { background: var(--primary-50); color: var(--primary); font-weight: 600; }
.mockup-content { display: flex; flex-direction: column; gap: 1rem; }
.mockup-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  box-shadow: var(--shadow-sm);
}
.mockup-bar {
  height: 10px;
  border-radius: 100px;
  background: var(--gray-300);
}
.mockup-bar.short { width: 60%; }
.mockup-bar.medium { width: 80%; }
.mockup-bar.primary { background: var(--primary-50); }
.mockup-bar.accent { background: #D1FAE5; }

@media (max-width: 768px) {
  .mockup-sidebar { grid-template-columns: 1fr; }
}

/* ───── STATS BAR ───── */
.stats-bar {
  background: var(--dark);
  padding: 2.5rem 1.5rem;
}
.stats-bar .container {
  display: flex;
  justify-content: center;
  gap: 4rem;
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-value {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--white);
  line-height: 1.2;
}
.stat-value .accent { color: var(--lime); }
.stat-label {
  font-size: 0.938rem;
  color: rgba(255, 255, 255, 0.6);
  margin-top: 0.25rem;
}

@media (max-width: 640px) {
  .stats-bar .container { gap: 2rem; }
  .stat-value { font-size: 1.75rem; }
}

/* ───── CARD GRID ───── */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.5rem;
}
.card-grid-3 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.card-grid-2 { grid-template-columns: repeat(auto-fit, minmax(400px, 1fr)); }

.card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}
.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: transparent;
}
.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.25rem;
}
.card-icon.indigo { background: var(--primary-50); color: var(--primary); }
.card-icon.green { background: #ECFDF5; color: var(--accent); }
.card-icon.coral { background: #FFF1F2; color: var(--coral); }
.card-icon.amber { background: #FFFBEB; color: #D97706; }
.card-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--dark);
  margin-bottom: 0.5rem;
}
.card-text {
  font-size: 0.938rem;
  color: var(--gray-500);
  line-height: 1.7;
}
.card-link {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.938rem;
  text-decoration: none;
  margin-top: 1rem;
  transition: gap 0.2s ease;
}
.card-link:hover { gap: 0.625rem; }

/* ───── WHY CHOOSE TABS ───── */
.why-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2.5rem;
  justify-content: center;
}
.why-tab {
  padding: 0.75rem 1.5rem;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all 0.25s ease;
  border: 1.5px solid var(--gray-300);
  background: var(--white);
  color: var(--gray-700);
  font-family: var(--font-sans);
}
.why-tab.active { background: var(--primary); color: var(--white); border-color: var(--primary); box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3); }
.why-tab:hover:not(.active) { border-color: var(--primary); color: var(--primary); }
.why-panel { display: none; animation: fadeUp 0.35s ease-out; }
.why-panel.active { display: block; }
.why-feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.25rem;
}
.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  background: var(--gray-50);
  transition: all 0.2s ease;
}
.why-feature-item:hover { background: var(--primary-50); }
.why-feature-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.why-feature-text h4 { font-size: 0.938rem; font-weight: 700; color: var(--dark); margin-bottom: 0.125rem; }
.why-feature-text p { font-size: 0.813rem; color: var(--gray-500); line-height: 1.5; }

/* ───── TESTIMONIALS ───── */
.testimonial-section { background: var(--gray-50); }
.carousel-container { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  padding: 0 0.75rem;
  display: flex;
  gap: 1.5rem;
}
.testimonial-card {
  flex: 1;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  display: flex;
  flex-direction: column;
}
.testimonial-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--primary);
  background: var(--primary-50);
  padding: 0.25rem 0.75rem;
  border-radius: 100px;
  margin-bottom: 1rem;
  align-self: flex-start;
}
.testimonial-quote {
  font-size: 1rem;
  color: var(--gray-700);
  line-height: 1.7;
  flex: 1;
  margin-bottom: 1.5rem;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: 0.75rem; }
.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary-light), var(--primary));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 1rem;
}
.testimonial-name { font-weight: 700; font-size: 0.938rem; color: var(--dark); }
.testimonial-role { font-size: 0.813rem; color: var(--gray-500); }
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  background: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  color: var(--gray-700);
  font-family: var(--font-sans);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); background: var(--primary-50); }
.carousel-dots {
  display: flex;
  gap: 0.5rem;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: all 0.25s ease;
  padding: 0;
}
.carousel-dot.active { background: var(--primary); width: 24px; border-radius: 100px; }

@media (max-width: 768px) {
  .carousel-slide { flex-direction: column; }
}

/* ───── PRICING ───── */
.pricing-card {
  background: var(--white);
  border: 1.5px solid var(--gray-100);
  border-radius: var(--radius-xl);
  padding: 2.5rem;
  text-align: center;
  transition: all 0.3s ease;
  position: relative;
}
.pricing-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 8px 40px rgba(79, 70, 229, 0.15);
}
.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 1rem;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.pricing-name { font-size: 1.25rem; font-weight: 700; color: var(--dark); margin-bottom: 0.5rem; }
.pricing-price { font-size: 3rem; font-weight: 800; color: var(--dark); line-height: 1.1; }
.pricing-price span { font-size: 1rem; font-weight: 500; color: var(--gray-500); }
.pricing-desc { font-size: 0.875rem; color: var(--gray-500); margin: 1rem 0 1.5rem; }
.pricing-features { list-style: none; text-align: left; margin-bottom: 2rem; display: flex; flex-direction: column; gap: 0.75rem; }
.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  font-size: 0.875rem;
  color: var(--gray-700);
}
.pricing-features .check {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #ECFDF5;
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 0.75rem;
}

/* ───── INTEGRATIONS ───── */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1rem;
}
.integration-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--gray-700);
  transition: all 0.2s ease;
}
.integration-item:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); border-color: transparent; }
.integration-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.75rem;
  color: var(--white);
}

/* ───── FAQ ───── */
.faq-list { display: flex; flex-direction: column; gap: 0.75rem; max-width: 800px; margin: 0 auto; }
.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 0.2s ease;
}
.faq-item:hover { border-color: var(--gray-300); }
.faq-item.open { border-color: var(--primary); box-shadow: 0 2px 12px rgba(79, 70, 229, 0.08); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
  color: var(--dark);
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  font-family: var(--font-sans);
  gap: 1rem;
}
.faq-question:hover { color: var(--primary); }
.faq-chevron {
  transition: transform 0.3s ease;
  flex-shrink: 0;
  color: var(--gray-500);
}
.faq-item.open .faq-chevron { transform: rotate(180deg); color: var(--primary); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-answer-inner {
  padding: 0 1.5rem 1.25rem;
  font-size: 0.938rem;
  color: var(--gray-500);
  line-height: 1.7;
}

/* ───── FOOTER ───── */
.footer {
  background: var(--dark);
  color: rgba(255, 255, 255, 0.7);
  padding: 4rem 1.5rem 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand { }
.footer-brand .logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
}
.footer-brand .logo .logo-icon {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 0.875rem;
  font-weight: 800;
}
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 300px; }
.footer-col h4 {
  color: var(--white);
  font-size: 0.813rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.25rem;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.625rem; }
.footer-col a {
  text-decoration: none;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.875rem;
  transition: color 0.2s ease;
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 0.813rem;
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ───── CTA BANNER ───── */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-xl);
  padding: 4rem 2.5rem;
  text-align: center;
  color: var(--white);
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.cta-banner h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); font-weight: 800; margin-bottom: 1rem; }
.cta-banner p { font-size: 1.125rem; opacity: 0.85; max-width: 540px; margin: 0 auto 2rem; line-height: 1.7; }
.btn-white {
  background: var(--white);
  color: var(--primary);
  font-weight: 700;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
}
.btn-white:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15); }

/* ───── TOOLS GRID ───── */
.tools-section { }
.tools-category { margin-bottom: 2rem; }
.tools-category-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-500);
  margin-bottom: 0.75rem;
}
.tools-tags { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.tool-tag {
  padding: 0.5rem 1rem;
  border-radius: 100px;
  font-size: 0.813rem;
  font-weight: 600;
  background: var(--gray-50);
  color: var(--gray-700);
  border: 1px solid var(--gray-100);
  transition: all 0.2s ease;
}
.tool-tag:hover { background: var(--primary-50); color: var(--primary); border-color: var(--primary-50); }

/* ───── STEPS ───── */
.steps { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2rem; counter-reset: step; }
.step-card {
  position: relative;
  padding: 2rem;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-100);
  counter-increment: step;
  transition: all 0.3s ease;
}
.step-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.step-number {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.25rem;
  margin-bottom: 1.25rem;
}
.step-card h3 { font-size: 1.25rem; font-weight: 700; color: var(--dark); margin-bottom: 0.5rem; }
.step-card p { font-size: 0.938rem; color: var(--gray-500); line-height: 1.7; }

/* ───── FEATURE SPLIT ───── */
.feature-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.feature-split.reverse { direction: rtl; }
.feature-split.reverse > * { direction: ltr; }
.feature-visual {
  background: var(--gray-50);
  border-radius: var(--radius-xl);
  padding: 2.5rem;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.feature-visual-inner {
  width: 100%;
  max-width: 400px;
}
@media (max-width: 768px) {
  .feature-split { grid-template-columns: 1fr; gap: 2rem; }
  .feature-split.reverse { direction: ltr; }
}

/* ───── SOCIAL PROOF ───── */
.social-proof-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
  padding: 2rem 0;
}
.social-proof-item {
  text-align: center;
  color: var(--gray-500);
  font-size: 0.875rem;
  font-weight: 600;
}
.social-proof-item .number {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--dark);
  display: block;
}

/* ───── RESOURCES ───── */
.resource-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 0.3s ease;
  text-decoration: none;
  color: inherit;
  display: block;
}
.resource-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.resource-thumb {
  height: 180px;
  background: linear-gradient(135deg, var(--primary-50), #ECFDF5);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.resource-body { padding: 1.5rem; }
.resource-body h3 { font-size: 1.063rem; font-weight: 700; color: var(--dark); margin-bottom: 0.375rem; }
.resource-body p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; }

/* ───── FILE TYPES ───── */
.file-type-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
}
.file-type-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
  transition: all 0.2s ease;
}
.file-type-item:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.file-type-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 0.75rem;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.file-type-name { font-weight: 600; font-size: 0.875rem; color: var(--dark); }

/* ───── SPOTLIGHT ───── */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
}
.spotlight-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}
.spotlight-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.spotlight-card h3 { font-size: 1.25rem; font-weight: 700; color: var(--dark); margin-bottom: 0.5rem; }
.spotlight-card p { font-size: 0.938rem; color: var(--gray-500); line-height: 1.7; }

/* ───── MEMBERSHIP FEATURES ───── */
.membership-stat {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 2rem;
  background: var(--primary-50);
  border-radius: var(--radius-xl);
  margin-bottom: 2rem;
}
.membership-stat .big-number {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1;
  white-space: nowrap;
}
.membership-stat .stat-info h3 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--dark);
  margin-bottom: 0.25rem;
}
.membership-stat .stat-info p {
  font-size: 0.938rem;
  color: var(--gray-500);
}
@media (max-width: 640px) {
  .membership-stat { flex-direction: column; text-align: center; }
  .membership-stat .big-number { font-size: 2.5rem; }
}

/* ───── ANIMATIONS ───── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.animate-on-scroll {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}
.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}
.stagger-1 { transition-delay: 0.1s; }
.stagger-2 { transition-delay: 0.2s; }
.stagger-3 { transition-delay: 0.3s; }
.stagger-4 { transition-delay: 0.4s; }

/* ───── MISC ───── */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.badge-primary { background: var(--primary-50); color: var(--primary); }
.badge-accent { background: #ECFDF5; color: var(--accent); }
.badge-coral { background: #FFF1F2; color: var(--coral); }

.divider {
  width: 100%;
  height: 1px;
  background: var(--gray-100);
}

.page-top { padding-top: 72px; }

.highlight-box {
  background: linear-gradient(135deg, var(--primary-50) 0%, #ECFDF5 100%);
  border-radius: var(--radius-xl);
  padding: 3rem;
}

@media (max-width: 768px) {
  .section { padding: 3.5rem 1rem; }
  .hero { padding-top: 6rem; padding-bottom: 3rem; }
  .hero-title { font-size: clamp(2rem, 6vw, 3rem); }
  .hero-subtitle { font-size: 1.063rem; }
  .card-grid-2 { grid-template-columns: 1fr; }
}

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800&display=swap');

:root {
  --primary: #4F46E5;
  --primary-dark: #3730A3;
  --primary-light: #818CF8;
  --primary-50: #EEF2FF;
  --accent: #10B981;
  --accent-dark: #059669;
  --coral: #F43F5E;
  --lime: #E6FF32;
  --dark: #0F172A;
  --gray-900: #1E293B;
  --gray-700: #334155;
  --gray-500: #64748B;
  --gray-300: #CBD5E1;
  --gray-100: #F1F5F9;
  --gray-50: #F8FAFC;
  --white: #FFFFFF;
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 4px 12px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 8px 30px rgba(15, 23, 42, 0.12);
  --shadow-xl: 0 20px 60px rgba(15, 23, 42, 0.15);
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font-sans);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ───── NAVBAR ───── */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  transition: box-shadow 0.3s ease;
}
.navbar.scrolled { box-shadow: var(--shadow-md); }
.navbar-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.navbar-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.navbar-logo .logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.1rem;
  font-weight: 800;
}
.nav-links { display: flex; align-items: center; gap: 0.25rem; list-style: none; }
.nav-links a {
  text-decoration: none;
  color: var(--gray-700);
  font-weight: 500;
  font-size: 0.938rem;
  padding: 0.5rem 0.875rem;
  border-radius: var(--radius);
  transition: all 0.2s ease;
}
.nav-links a:hover { color: var(--primary); background: var(--primary-50); }
.nav-links a.active { color: var(--primary); background: var(--primary-50); }
.nav-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--primary);
  color: var(--white) !important;
  font-weight: 600 !important;
  padding: 0.625rem 1.25rem !important;
  border-radius: var(--radius) !important;
  transition: all 0.2s ease !important;
  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3);
}
.nav-cta:hover { background: var(--primary-dark) !important; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(79, 70, 229, 0.4) !important; }
.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--gray-700);
}
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  padding: 1.5rem;
  flex-direction: column;
  gap: 0.5rem;
  overflow-y: auto;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  text-decoration: none;
  color: var(--gray-700);
  font-weight: 500;
  font-size: 1.1rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius);
  transition: all 0.2s ease;
}
.mobile-nav a:hover { color: var(--primary); background: var(--primary-50); }
.mobile-nav .nav-cta-mobile {
  display: block;
  text-align: center;
  background: var(--primary);
  color: var(--white);
  font-weight: 600;
  padding: 0.875rem 1.25rem;
  border-radius: var(--radius);
  margin-top: 1rem;
}

@media (max-width: 1024px) {
  .nav-links { display: none; }
  .hamburger { display: block; }
}

/* ───── SECTIONS ───── */
.section { padding: 5rem 1.5rem; }
.section-sm { padding: 3rem 1.5rem; }
.container { max-width: 1200px; margin: 0 auto; }
.container-narrow { max-width: 900px; margin: 0 auto; }
.section-label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.813rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  background: var(--primary-50);
  padding: 0.375rem 1rem;
  border-radius: 100px;
  margin-bottom: 1rem;
}
.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  line-height: 1.15;
  color: var(--dark);
  margin-bottom: 1rem;
}
.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-500);
  line-height: 1.7;
  max-width: 640px;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ───── HERO ───── */
.hero {
  padding-top: 8rem;
  padding-bottom: 4rem;
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--white) 50%, #ECFDF5 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(79, 70, 229, 0.06) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; text-align: center; }
.hero-title {
  font-size: clamp(2.5rem, 5.5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  color: var(--dark);
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}
.hero-title .highlight {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-500);
  max-width: 640px;
  margin: 0 auto 2.5rem;
  line-height: 1.7;
}
.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

/* ───── BUTTONS ───── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 1rem;
  padding: 0.875rem 2rem;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
  line-height: 1;
}
.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 2px 12px rgba(79, 70, 229, 0.35);
}
