  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.25rem;
}
.card-icon.indigo { background: var(--primary-50); color: var(--primary); }
.card-icon.green { background: #ECFDF5; color: var(--accent); }
.card-icon.coral { background: #FFF1F2; color: var(--coral); }
.card-icon.amber { background: #FFFBEB; color: #D97706; }
.card-title {
  font-size: 1.25rem;
  font-weight: 700;
