  gap: 0.5rem;
  margin-bottom: 2.5rem;
  justify-content: center;
}
.why-tab {
  padding: 0.75rem 1.5rem;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all 0.25s ease;
  border: 1.5px solid var(--gray-300);
  background: var(--white);
  color: var(--gray-700);
  font-family: var(--font-sans);
}
.why-tab.active { background: var(--primary); color: var(--white); border-color: var(--primary); box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3); }
.why-tab:hover:not(.active) { border-color: var(--primary); color: var(--primary); }
.why-panel { display: none; animation: fadeUp 0.35s ease-out; }
.why-panel.active { display: block; }
.why-feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.25rem;
}
.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  background: var(--gray-50);
