}
.why-feature-text h4 { font-size: 0.938rem; font-weight: 700; color: var(--dark); margin-bottom: 0.125rem; }
.why-feature-text p { font-size: 0.813rem; color: var(--gray-500); line-height: 1.5; }

/* ───── TESTIMONIALS ───── */
.testimonial-section { background: var(--gray-50); }
.carousel-container { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  padding: 0 0.75rem;
  display: flex;
  gap: 1.5rem;
}
.testimonial-card {
  flex: 1;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  display: flex;
  flex-direction: column;
}
.testimonial-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--primary);
  background: var(--primary-50);
